    s('REQ-1-3-1', 'audit regression: complete import exposes AA columns and rows beyond the initial viewport', "await page.goto('/'); await h.button(page,'Import CSV').click(); const name=h.unique();\nconst dialog=page.getByRole('dialog',{name:'Import CSV',exact:true});\nconst rows=Array.from({length:52},(_,r)=>Array.from({length:28},(_,c)=>`r${r+1}c${c+1}`).join(','));\nawait h.field(dialog,'CSV file').setInputFiles({name:`${name}.csv`,mimeType:'text/csv',buffer:Buffer.from(rows.join('\\n'))});\nawait h.button(dialog,'Confirm import').click(); await expect(h.text(page,name).first()).toBeVisible();\nawait h.persisted(page,()=>h.values(page,{A1:'r1c1',Z1:'r1c26',AA1:'r1c27',AB1:'r1c28',A51:'r51c1',AA52:'r52c27',AB52:'r52c28'}));", requires=['REQ-1-3-1'])
    s('REQ-2-1-4', 'audit regression: deleting the third of four sheets selects an actual adjacent survivor', "await h.blank(page);\nfor(let i=2;i<=4;i++){await h.button(page,'Add worksheet').click();await expect(h.tab(page,`Sheet${i}`)).toHaveAttribute('aria-selected','true');}\nawait h.tab(page,'Sheet3').click(); await h.sheetMenu(page,'Sheet3','Delete');\nawait h.button(page.getByRole('dialog',{name:'Delete worksheet',exact:true}),'Delete worksheet').click();\nawait h.persisted(page,async()=>{await h.tabOrder(page,['Sheet1','Sheet2','Sheet4']);\n  await expect(page.getByRole('tab',{selected:true})).toHaveAccessibleName(/^Sheet(?:2|4)$/);});", requires=['REQ-2-1-4', 'REQ-1-2-1', 'REQ-2-1-1', 'REQ-2-1-2'])
    s('REQ-4-2-2', 'audit regression: =A0 displays a stable #REF! and repairing it restores dependents', 'await h.blank(page); await h.edit(page,\'A1\',\'6\'); await h.edit(page,\'B1\',"=A0"); await h.edit(page,\'C1\',\'=B1+1\');\nawait h.persisted(page,async()=>{await h.formula(page,\'B1\',"=A0","#REF!");await h.values(page,{A1:\'6\',C1:"#REF!"});});\nawait h.edit(page,\'B1\',\'=A1+1\'); await h.persisted(page,()=>h.values(page,{A1:\'6\',B1:\'7\',C1:\'8\'}));', requires=['REQ-4-2-2', 'REQ-1-2-1', 'REQ-3-1-1', 'REQ-4-1-1', 'REQ-4-2-1'])
