    s('REQ-4-2-2', 'audit regression: =. displays a stable #ERROR! and repairing it restores dependents', 'await h.blank(page); await h.edit(page,\'A1\',\'6\'); await h.edit(page,\'B1\',"=."); await h.edit(page,\'C1\',\'=B1+1\');\nawait h.persisted(page,async()=>{await h.formula(page,\'B1\',"=.","#ERROR!");await h.values(page,{A1:\'6\',C1:"#ERROR!"});});\nawait h.edit(page,\'B1\',\'=A1+1\'); await h.persisted(page,()=>h.values(page,{A1:\'6\',B1:\'7\',C1:\'8\'}));', requires=['REQ-4-2-2', 'REQ-1-2-1', 'REQ-3-1-1', 'REQ-4-1-1', 'REQ-4-2-1'])
    s('REQ-4-1-1', 'audit regression: zero arithmetic and a dependent result remain visible and persisted', "await h.blank(page); await h.edit(page,'A1','=1-1'); await h.edit(page,'B1','=A1+1');\nawait h.persisted(page,async()=>{await h.formula(page,'A1','=1-1','0');await h.formula(page,'B1','=A1+1','1');});", requires=['REQ-4-1-1', 'REQ-1-2-1', 'REQ-3-1-1'])
    s('REQ-3-1-3', 'audit regression: one pointer move commits and persists the entire drag rectangle', "await h.blank(page); const a=await h.cell(page,'A1').boundingBox(),b=await h.cell(page,'C3').boundingBox();\nexpect(a).not.toBeNull();expect(b).not.toBeNull();\nawait page.mouse.move(a!.x+a!.width/2,a!.y+a!.height/2);await page.mouse.down();\nawait page.mouse.move(b!.x+b!.width/2,b!.y+b!.height/2);await page.mouse.up();\nawait h.persisted(page,()=>h.selection(page,['A1','B1','C1','A2','B2','C2','A3','B3','C3'],['D1','A4']));", requires=['REQ-3-1-3', 'REQ-1-2-1'])
    s('REQ-5-1-1', 'audit regression: Ascending uses chronological order for unambiguous non-ISO dates', '// Both dates are unambiguous and parseable; their lexical and chronological orders differ.\nexpect(Number.isFinite(Date.parse(\'1 October 2026\'))).toBe(true);expect(Number.isFinite(Date.parse(\'2 February 2026\'))).toBe(true);\nawait h.blank(page);await h.paste(page,\'A1\',\'Date\\tRecord\\n1 October 2026\\tlate\\n2 February 2026\\tearly-first\\n2 February 2026\\tearly-second\');\nawait h.range(page,\'A1\',\'B4\');await h.data(page,\'Sort range\');const dialog=page.getByRole(\'dialog\',{name:\'Sort range\',exact:true});\nawait dialog.getByRole(\'checkbox\',{name:\'Data has header row\',exact:true}).check();await h.choose(dialog,\'Sort by\',\'Date\');await h.choose(dialog,\'Order\',"Ascending");await h.button(dialog,\'Sort\').click();\nawait h.persisted(page,()=>h.values(page,{"A1": "Date", "B1": "Record", "A2": "2 February 2026", "B2": "early-first", "A3": "2 February 2026", "B3": "early-second", "A4": "1 October 2026", "B4": "late"}));', requires=['REQ-5-1-1', 'REQ-1-2-1', 'REQ-3-1-1', 'REQ-3-1-2', 'REQ-3-1-3'])
    s('REQ-5-1-1', 'audit regression: Descending uses chronological order for unambiguous non-ISO dates', '// Both dates are unambiguous and parseable; their lexical and chronological orders differ.\nexpect(Number.isFinite(Date.parse(\'1 October 2026\'))).toBe(true);expect(Number.isFinite(Date.parse(\'2 February 2026\'))).toBe(true);\nawait h.blank(page);await h.paste(page,\'A1\',\'Date\\tRecord\\n2 February 2026\\tearly-first\\n1 October 2026\\tlate\\n2 February 2026\\tearly-second\');\nawait h.range(page,\'A1\',\'B4\');await h.data(page,\'Sort range\');const dialog=page.getByRole(\'dialog\',{name:\'Sort range\',exact:true});\nawait dialog.getByRole(\'checkbox\',{name:\'Data has header row\',exact:true}).check();await h.choose(dialog,\'Sort by\',\'Date\');await h.choose(dialog,\'Order\',"Descending");await h.button(dialog,\'Sort\').click();\nawait h.persisted(page,()=>h.values(page,{"A1": "Date", "B1": "Record", "A2": "1 October 2026", "B2": "late", "A3": "2 February 2026", "B3": "early-first", "A4": "2 February 2026", "B4": "early-second"}));', requires=['REQ-5-1-1', 'REQ-1-2-1', 'REQ-3-1-1', 'REQ-3-1-2', 'REQ-3-1-3'])
    s('REQ-3-1-1', 'audit regression: failed grid Enter keeps both the original cell and formula bar before retry', "await h.blank(page);await h.cell(page,'A1').dblclick();await h.field(page,'Edit A1').fill('original');\nconst write=await h.learnWrite(page,async()=>{await h.field(page,'Edit A1').press('Enter');await h.values(page,{A1:'original'});});\nawait page.reload();await h.cell(page,'A1').dblclick();await h.field(page,'Edit A1').fill('rejected');\nconst fault=await h.rejectWrites(page,write);\ntry {await h.field(page,'Edit A1').press('Enter');await fault.assertInjected();\n  await expect(h.saveFailureReason(page).first()).toBeVisible();await h.values(page,{A1:'original'});\n  await expect(h.cell(page,'A1')).toHaveAttribute('aria-selected','true');await expect(h.field(page,'Formula bar')).toHaveValue('original');\n} finally {await fault.remove();}\nawait h.edit(page,'A1','retried',true);await h.persisted(page,()=>h.values(page,{A1:'retried'}));", requires=['REQ-3-1-1', 'REQ-1-2-1'])
    s('REQ-3-1-3', 'audit regression: late selection response cannot replace a subsequent successful cell edit', "await h.blank(page);await page.reload();\n// Learn the request fingerprint from a real selection, without interpreting its payload/schema.\nconst write=await h.learnWrite(page,()=>h.cell(page,'B1').click());await h.cell(page,'A1').click();await page.reload();\nlet release!:()=>void,arrived!:()=>void,finished!:()=>void;\nconst gate=new Promise<void>(resolve=>release=resolve),ready=new Promise<void>(resolve=>arrived=resolve),done=new Promise<void>(resolve=>finished=resolve);\nlet held=false;\nconst intercept=async(route:any)=>{const req=route.request();\n  if(!held&&h.matchesWrite(req,write)&&req.postData()===write.body){held=true;const response=await route.fetch();arrived();await gate;await route.fulfill({response});finished();}\n  else await route.continue();};\nawait page.route('**/*',intercept);\ntry {await h.cell(page,'B1').click();await Promise.race([ready,new Promise((_,reject)=>setTimeout(()=>reject(new Error('HARNESS_UNSUPPORTED: selection write was not intercepted')),10000))]);\n  await h.field(page,'Formula bar').fill('saved-after-selection');await h.field(page,'Formula bar').press('Enter');await h.values(page,{B1:'saved-after-selection'});\n  release();await done;await h.persisted(page,()=>h.values(page,{B1:'saved-after-selection'}));\n} finally {release();await page.unroute('**/*',intercept);}", requires=['REQ-3-1-3', 'REQ-1-2-1', 'REQ-3-1-1'])
    s('REQ-5-2-1', 'audit regression: single-cell number error uses between while persisted B3 multi-cell boundary uses from', "await h.blank(page);await h.edit(page,'A1','50');await h.validation(page,'A1','A1');await h.edit(page,'A1','101');\nawait expect(h.text(page,'Please enter a number between 0 and 100').first()).toBeVisible();await h.values(page,{A1:'50'});\nawait h.edit(page,'B3','50');await h.validation(page,'B2','B3');await page.reload();await h.edit(page,'B3','101');\nawait expect(h.text(page,'Please enter a number from 0 to 100').first()).toBeVisible();await h.persisted(page,()=>h.values(page,{A1:'50',B3:'50'}));", requires=['REQ-5-2-1', 'REQ-1-2-1', 'REQ-3-1-1', 'REQ-3-1-3'])
    s('REQ-5-2-1', 'audit regression: failed rule modify retains the dialog and previous constraint until a successful retry', 'await h.blank(page);await h.validation(page,\'A1\',\'A1\');\nawait h.data(page,\'Data validation\');const dialog=page.getByRole(\'dialog\',{name:\'Data validation\',exact:true});\nawait h.field(dialog,\'Maximum\').fill(\'80\');\nconst write=await h.learnWrite(page,async()=>{await h.button(dialog,\'Save\').click();await expect(dialog).toBeHidden();});\nawait h.data(page,\'Data validation\');await h.field(dialog,\'Maximum\').fill(\'100\');await h.button(dialog,\'Save\').click();await expect(dialog).toBeHidden();\nawait page.reload();await h.data(page,\'Data validation\');\nawait h.field(dialog,\'Maximum\').fill(\'20\');\nconst fault=await h.rejectWrites(page,write);\ntry {await h.button(dialog,"Save").click();await fault.assertInjected();\n  await expect(dialog).toBeVisible();await expect(h.saveFailureReason(dialog).first()).toBeVisible();\n} finally {await fault.remove();}\nawait page.reload();await h.edit(page,\'A1\',\'101\');await expect(h.text(page,\'Please enter a number between 0 and 100\').first()).toBeVisible();await h.values(page,{A1:\'\'});\nawait h.data(page,\'Data validation\');await expect(h.field(dialog,\'Maximum\')).toHaveValue(\'100\');\nawait h.field(dialog,\'Maximum\').fill(\'20\');await h.button(dialog,\'Save\').click();await expect(dialog).toBeHidden();\nawait h.edit(page,\'A1\',\'21\');await expect(h.text(page,\'Please enter a number between 0 and 20\').first()).toBeVisible();await h.values(page,{A1:\'\'});\nawait h.edit(page,\'A1\',\'20\');await h.persisted(page,()=>h.values(page,{A1:\'20\'}));', requires=['REQ-5-2-1', 'REQ-1-2-1', 'REQ-3-1-1', 'REQ-3-1-3'])
    s('REQ-5-2-1', 'audit regression: failed rule delete retains the dialog and previous constraint until a successful retry', 'await h.blank(page);await h.validation(page,\'A1\',\'A1\');\nawait h.data(page,\'Data validation\');const dialog=page.getByRole(\'dialog\',{name:\'Data validation\',exact:true});\nconst write=await h.learnWrite(page,async()=>{await h.button(dialog,\'Delete rule\').click();await expect(dialog).toBeHidden();});\nawait h.validation(page,\'A1\',\'A1\');await page.reload();await h.data(page,\'Data validation\');\nconst fault=await h.rejectWrites(page,write);\ntry {await h.button(dialog,"Delete rule").click();await fault.assertInjected();\n  await expect(dialog).toBeVisible();await expect(h.saveFailureReason(dialog).first()).toBeVisible();\n} finally {await fault.remove();}\nawait page.reload();await h.edit(page,\'A1\',\'101\');await expect(h.text(page,\'Please enter a number between 0 and 100\').first()).toBeVisible();await h.values(page,{A1:\'\'});\nawait h.data(page,\'Data validation\');await expect(h.field(dialog,\'Maximum\')).toHaveValue(\'100\');\nawait h.button(dialog,\'Delete rule\').click();await expect(dialog).toBeHidden();await h.edit(page,\'A1\',\'101\');await h.persisted(page,()=>h.values(page,{A1:\'101\'}));', requires=['REQ-5-2-1', 'REQ-1-2-1', 'REQ-3-1-1', 'REQ-3-1-3'])
    s('REQ-5-2-1', 'audit regression: modified inclusive number bounds become effective immediately without changing existing values', "await h.blank(page);await h.edit(page,'A1','10');await h.edit(page,'A2','15');await h.numericRule(page,'A1','A2','0','100');\nawait h.cell(page,'A2').click();await h.data(page,'Data validation');const dialog=page.getByRole('dialog',{name:'Data validation',exact:true});\nawait expect(h.field(dialog,'Maximum')).toHaveValue('100');await h.field(dialog,'Maximum').fill('20');await h.button(dialog,'Save').click();await expect(dialog).toBeHidden();\nawait h.values(page,{A1:'10',A2:'15'});await h.edit(page,'A2','21');await expect(h.text(page,'Please enter a number between 0 and 20').first()).toBeVisible();await h.values(page,{A1:'10',A2:'15'});\nawait h.edit(page,'A2','20');await h.persisted(page,()=>h.values(page,{A1:'10',A2:'20'}));", requires=['REQ-5-2-1', 'REQ-1-2-1', 'REQ-3-1-1', 'REQ-3-1-3'])
    s('REQ-5-3-1', 'audit regression: SUM refresh with no numeric values preserves results and source before zero-value retry', 'await h.sourceData(page);await h.pivot(page,"SUM");await h.values(page,{B2:"40",B4:"60"});\nawait h.tab(page,\'Sheet1\').click();await h.paste(page,\'B2\',\'bad\\ntext\\ninvalid\');await h.values(page,{B2:\'bad\',B3:\'text\',B4:\'invalid\'});await h.tab(page,\'Pivot1\').click();\nawait h.button(page,\'Refresh pivot table\').click();await expect(h.text(page,\'Value field requires numeric values\').first()).toBeVisible();\nawait h.persisted(page,()=>h.values(page,{B2:"40",B4:"60"}));\nawait h.tab(page,\'Sheet1\').click();await h.values(page,{B2:\'bad\',B3:\'text\',B4:\'invalid\'});await h.paste(page,\'B2\',\'0\\n0\\n0\');await h.values(page,{B2:\'0\',B3:\'0\',B4:\'0\'});\nawait h.tab(page,\'Pivot1\').click();await h.button(page,\'Refresh pivot table\').click();await h.persisted(page,()=>h.values(page,{B1:"SUM of Sales",B2:\'0\',B3:\'0\',B4:\'0\'}));', requires=['REQ-5-3-1', 'REQ-1-2-1', 'REQ-3-1-1', 'REQ-3-1-2', 'REQ-3-1-3', 'REQ-4-1-1', 'REQ-4-2-1'])
    s('REQ-5-3-1', 'audit regression: AVERAGE refresh with no numeric values preserves results and source before zero-value retry', 'await h.sourceData(page);await h.pivot(page,"AVERAGE");await h.values(page,{B2:"20",B4:"20"});\nawait h.tab(page,\'Sheet1\').click();await h.paste(page,\'B2\',\'bad\\ntext\\ninvalid\');await h.values(page,{B2:\'bad\',B3:\'text\',B4:\'invalid\'});await h.tab(page,\'Pivot1\').click();\nawait h.button(page,\'Refresh pivot table\').click();await expect(h.text(page,\'Value field requires numeric values\').first()).toBeVisible();\nawait h.persisted(page,()=>h.values(page,{B2:"20",B4:"20"}));\nawait h.tab(page,\'Sheet1\').click();await h.values(page,{B2:\'bad\',B3:\'text\',B4:\'invalid\'});await h.paste(page,\'B2\',\'0\\n0\\n0\');await h.values(page,{B2:\'0\',B3:\'0\',B4:\'0\'});\nawait h.tab(page,\'Pivot1\').click();await h.button(page,\'Refresh pivot table\').click();await h.persisted(page,()=>h.values(page,{B1:"AVERAGE of Sales",B2:\'0\',B3:\'0\',B4:\'0\'}));', requires=['REQ-5-3-1', 'REQ-1-2-1', 'REQ-3-1-1', 'REQ-3-1-2', 'REQ-3-1-3', 'REQ-4-1-1', 'REQ-4-2-1'])
    s('REQ-5-2-1', 'audit regression: failed first rule save reports an error without closing or installing the rule', "await h.blank(page);await h.edit(page,'A1','original');await h.values(page,{A1:'original'});\nconst setup=await h.prepareValidation(page,'A1','A1');\nconst write=await h.learnWrite(page,async()=>{await h.button(setup,'Save').click();await expect(setup).toBeHidden();});\nawait h.data(page,'Data validation');await h.button(setup,'Delete rule').click();await expect(setup).toBeHidden();await page.reload();\nawait h.data(page,'Data validation');const dialog=page.getByRole('dialog',{name:'Data validation',exact:true});await h.choose(dialog,'Rule type','Number range');\nawait h.field(dialog,'Minimum').fill('0');await h.field(dialog,'Maximum').fill('20');const fault=await h.rejectWrites(page,write);\ntry{await h.button(dialog,'Save').click();await fault.assertInjected();await expect(dialog).toBeVisible();await expect(h.saveFailureReason(dialog).first()).toBeVisible();}\nfinally{await fault.remove();}\nawait page.reload();await h.edit(page,'A1','21');await h.values(page,{A1:'21'});await h.data(page,'Data validation');await expect(h.button(dialog,'Delete rule')).toHaveCount(0);\nawait h.choose(dialog,'Rule type','Number range');await h.field(dialog,'Minimum').fill('0');await h.field(dialog,'Maximum').fill('20');await h.button(dialog,'Save').click();await expect(dialog).toBeHidden();await h.edit(page,'A1','22');\nawait expect(h.text(page,'Please enter a number between 0 and 20').first()).toBeVisible();await h.persisted(page,()=>h.values(page,{A1:'21'}));", requires=['REQ-5-2-1', 'REQ-1-2-1', 'REQ-3-1-1'])
    s('REQ-5-1-1', 'audit regression: failed sort keeps its dialog and original order before retry', "await h.sourceData(page);await h.range(page,'A1','C4');await h.data(page,'Sort range');const dialog=page.getByRole('dialog',{name:'Sort range',exact:true});\nawait dialog.getByRole('checkbox',{name:'Data has header row',exact:true}).check();await h.choose(dialog,'Sort by','Sales');await h.choose(dialog,'Order','Descending');const write=await h.learnWrite(page,async()=>{await h.button(dialog,'Sort').click();await h.values(page,{B2:'30',B3:'20',B4:'10'});});\nawait h.range(page,'A1','C4');await h.data(page,'Sort range');await dialog.getByRole('checkbox',{name:'Data has header row',exact:true}).check();await h.choose(dialog,'Sort by','Sales');await h.choose(dialog,'Order','Ascending');const fault=await h.rejectWrites(page,write);\ntry{await h.button(dialog,'Sort').click();await fault.assertInjected();await expect(dialog).toBeVisible();await expect(h.saveFailureReason(dialog).first()).toBeVisible();await h.chosen(dialog,'Sort by','Sales');await h.chosen(dialog,'Order','Ascending');}\nfinally{await fault.remove();}\n// A modal legitimately hides the background from the accessibility tree.\nawait h.button(dialog,'Cancel').click();await h.persisted(page,()=>h.values(page,{A2:'East',B2:'30',A3:'North',B3:'20',A4:'East',B4:'10'}));\nawait h.range(page,'A1','C4');await h.data(page,'Sort range');await dialog.getByRole('checkbox',{name:'Data has header row',exact:true}).check();await h.choose(dialog,'Sort by','Sales');await h.choose(dialog,'Order','Ascending');\nawait h.button(dialog,'Sort').click();await expect(dialog).toBeHidden();await h.persisted(page,()=>h.values(page,{A2:'East',B2:'10',A3:'North',B3:'20',A4:'East',B4:'30'}));", requires=['REQ-5-1-1', 'REQ-1-2-1', 'REQ-3-1-2', 'REQ-3-1-3'])
    s('REQ-5-1-2', 'audit regression: failed filter apply preserves the saved predicate and supports retry', "await h.sourceData(page);await h.range(page,'A1','C4');await h.data(page,'Create filter');await h.filterValues(page,'Region',['East']);await h.visibleRows(page,['A2','A4'],['A3']);\nawait h.button(page,'Filter Region').click();const dialog=page.getByRole('dialog',{name:'Filter Region',exact:true});\nawait h.button(dialog,'Clear selection').click();await dialog.getByRole('checkbox',{name:'North',exact:true}).check();\nconst write=await h.learnWrite(page,async()=>{await h.button(dialog,'Apply').click();await expect(dialog).toBeHidden();await h.visibleRows(page,['A3'],['A2','A4']);});\nawait h.button(page,'Filter Region').click();await h.button(dialog,'Clear selection').click();await dialog.getByRole('checkbox',{name:'East',exact:true}).check();\nconst fault=await h.rejectWrites(page,write);\ntry{await h.button(dialog,'Apply').click();await fault.assertInjected();await expect(dialog).toBeVisible();await expect(h.saveFailureReason(dialog).first()).toBeVisible();await expect(dialog.getByRole('checkbox',{name:'East',exact:true})).toBeChecked();}\nfinally{await fault.remove();}\nawait h.button(dialog,'Cancel').click();await h.persisted(page,()=>h.visibleRows(page,['A3'],['A2','A4']));\nawait h.button(page,'Filter Region').click();await h.button(dialog,'Clear selection').click();await dialog.getByRole('checkbox',{name:'East',exact:true}).check();\nawait h.button(dialog,'Apply').click();await expect(dialog).toBeHidden();await h.persisted(page,()=>h.visibleRows(page,['A2','A4'],['A3']));", requires=['REQ-5-1-2', 'REQ-1-2-1', 'REQ-3-1-2', 'REQ-3-1-3'])
    s('REQ-5-1-1', 'audit regression: numeric formula results sort with complete records and retain their original expressions', "await h.blank(page);await h.paste(page,'A1','Record\\tKey\\nten\\t=10\\ntwo\\t=2\\nthree\\t=3');await h.values(page,{B2:'10',B3:'2',B4:'3'});\nawait h.range(page,'A1','B4');await h.data(page,'Sort range');const dialog=page.getByRole('dialog',{name:'Sort range',exact:true});await dialog.getByRole('checkbox',{name:'Data has header row',exact:true}).check();await h.choose(dialog,'Sort by','Key');await h.choose(dialog,'Order','Ascending');await h.button(dialog,'Sort').click();\nawait h.persisted(page,async()=>{await h.values(page,{A1:'Record',B1:'Key',A2:'two',A3:'three',A4:'ten'});await h.formula(page,'B2','=2','2');await h.formula(page,'B3','=3','3');await h.formula(page,'B4','=10','10');});", requires=['REQ-5-1-1', 'REQ-1-2-1', 'REQ-3-1-1', 'REQ-3-1-2', 'REQ-3-1-3', 'REQ-4-1-1'])
    s('REQ-5-3-1', 'audit regression: AVERAGE includes formula zero as a numeric record in group and grand totals', "await h.sourceData(page);await h.edit(page,'B2','=1-1');await h.edit(page,'B3','2');await h.edit(page,'B4','=1-1');await h.values(page,{B2:'0',B3:'2',B4:'0'});await h.pivot(page,'AVERAGE');\nawait h.persisted(page,async()=>{await h.values(page,{A2:'East',B2:'0',A3:'North',B3:'2',A4:'Grand Total'});expect(Number(await h.cell(page,'B4').innerText())).toBeCloseTo(2/3,10);});\nawait h.tab(page,'Sheet1').click();await h.formula(page,'B2','=1-1','0');await h.formula(page,'B4','=1-1','0');", requires=['REQ-5-3-1', 'REQ-1-2-1', 'REQ-2-1-1', 'REQ-2-1-2', 'REQ-3-1-1', 'REQ-3-1-2', 'REQ-3-1-3', 'REQ-4-1-1'])
